extra=[];dest=HERE/'attributed_source_audits';dest.mkdir(exist_ok=True)
for p,sid,name in [(349,'ASTRA-V-INK-MARK-349','identification_349.json'),(350,'ASTRA-V-CH-CONSTANTS-350;ASTRA-V-CH-MODULUS-350','identification_350.json')]:
    rel='review/expose_v/'+name;raw=(ROOT/rel).read_bytes();(dest/name).write_bytes(raw)
    extra.append(dict(record_type='attributed_source_audit_packet',page=p,source_id=sid,source_packet=rel,contribution_copy='review/english/contributions/exposes_v_vi/attributed_source_audits/'+name,packet_sha256=hashlib.sha256(raw).hexdigest(),decision='Exact frozen French proof packet. It preserves the physical small-mark observation,the single-product coefficient,the actual scalar/rank conventions,the zero-constant character map and the rational-modulus counterexample. No new image inspection is claimed by this translation transfer.'))
for p,newpara,reason in [(346,True,'The full6.1 construction and both local continuation blocks end before Definition6.2.'),(347,True,'The Chern-class motivation ends before numbered paragraph6.3.'),(348,True,'The final scalar-compatibility display ends before the source new paragraph extending ch;checker346_350#13 explicitly records this break.'),(349,False,'The349 on deduit continues with350 donc and its congruence;English we deduce/therefore retains that boundary.'),(350,False,'The350 case continues with351 where A is the ring,as in the source.')]:
    f=(HERE/'source_packets'/str(p)/'current.tex').read_text();g=(HERE/'source_packets'/str(p+1)/'current.tex').read_text();e=(HERE/'translations'/f'{p}.tex').read_text();n=(HERE/'translations'/f'{p+1}.tex').read_text()
    assert e.endswith('\n\n')==newpara;assert not n.startswith('\n')
    extra.append(dict(record_type='manually_compared_source_folio_join',after=p,before=p+1,paragraph_break=newpara,source_tail=f[-400:],source_head=g[:400],English_tail=e[-250:],English_head=n[:250],source_page_sha256s={str(p):sha(f),str(p+1):sha(g)},reason=reason))
